/**
 *
 * BreadcrumbLink is a component that displays a navigable link in the breadcrumb.
 *
 * [Live Demo](https://www.primereact.org/breadcrumb/)
 *
 * @module BreadcrumbLink
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { BreadcrumbRootInstance } from './BreadcrumbRoot.types';
/**
 * Defines passthrough(pt) options type in BreadcrumbLink component.
 */
export type BreadcrumbLinkPassThroughType<E> = PassThroughType<BreadcrumbLinkInstance, E>;
/**
 * Defines passthrough(pt) options of BreadcrumbLink component.
 */
export interface BreadcrumbLinkPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: BreadcrumbLinkPassThroughType<React.HTMLAttributes<HTMLAnchorElement>>;
}
/**
 * Defines valid properties in BreadcrumbLink component.
 */
export interface BreadcrumbLinkProps extends BaseComponentProps<BreadcrumbLinkInstance, unknown, BreadcrumbLinkPassThrough> {
}
/**
 * Defines valid state in BreadcrumbLink component.
 */
export interface BreadcrumbLinkState {
}
/**
 * Defines the methods and properties exposed by BreadcrumbLink component.
 */
export interface BreadcrumbLinkExposes {
    /**
     * Instance of the Breadcrumb component.
     */
    breadcrumb: BreadcrumbRootInstance | undefined | null;
}
/**
 * Instance of BreadcrumbLink component.
 */
export type BreadcrumbLinkInstance = ComponentInstance<BreadcrumbLinkProps, BreadcrumbLinkState, BreadcrumbLinkExposes>;
